//! This module turns the token stream generated by the [crate::lexing]
//! into an AST (abstract syntax tree), with wich we can catch syntax errors and generate the IR
//! [intermediate representation](https://llvm.org/docs/LangRef.html)

use crate::{common::Literal, lexing::Token};

/// Defines the nodes of the AST
pub enum TreeNode {
    ProgramBlock(Vec<TreeNode>),
    Function {
        name: String,
        return_value: Type,
        arguments: Vec<(String, Type)>,
    },
    VariableDeclaration {
        name: String,
        var_type: Type,
    },
    IfStatement {
        // expression: ?
        block: Box<TreeNode>,
    },
    Literal(Literal),
}

/// The most primitive types that can't be represented by the others
pub enum PrimitiveType {
    Char,
    Bool,
    Int,
    Float,
}

/// A complex representation of types built on a foundation of primitives
pub enum Type {
    Primitive(PrimitiveType),
    Collection(Vec<Type>),
    Pointer(Box<Type>),
}

/// A parser struct used to parse a token stream
pub struct Parser {
    current_tree: TreeNode,
    tokens: Vec<Token>,
}

impl Parser {
    /// Create a new parser instance
    pub fn new(tokens: Vec<Token>) -> Self {
        Self {
            current_tree: TreeNode::ProgramBlock(vec![]),
            tokens,
        }
    }
    /// Process the list of tokens
    pub fn process() -> TreeNode {
        todo!()
    }
}

